<script setup lang="ts">
import {computed,ref} from 'vue';import {onLoad,onShow,onHide} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {money} from '@shared/utils/money';import {CURRENCIES} from '@shared/utils/constants';import {idempotencyKey} from '@shared/net/http-client';import {managementTime} from '@/shared/management';import {fixedMinor} from '@/shared/stored-value-form';import {definiteGovernanceRejection} from '@/shared/stored-value-governance-errors';import {encodeFinanceCommand,restoreFinanceCommand,financeStorageKey} from '@/shared/stored-value-finance-command';import type {FinanceCommand} from '@/shared/stored-value-finance-command';import type {SvSettlementBill,SvSettlementItem,SvSettlementEvent,SvSettlementPayment,SvBillActions,SvFinanceCapability} from '@/api/stored-value-finance';
const {t}=useI18n();const m=ref(''),no=ref(''),actor=ref('');const bill=ref<SvSettlementBill|null>(null),access=ref<SvBillActions>({payerActions:[],payeeActions:[]}),capability=ref<SvFinanceCapability|null>(null);const items=ref<SvSettlementItem[]>([]),payments=ref<SvSettlementPayment[]>([]),events=ref<SvSettlementEvent[]>([]),itemNext=ref<string|null>(null),paymentNext=ref<string|null>(null),eventNext=ref<string|null>(null);const loaded=ref(false);const loading=ref(true),failed=ref(false),busy=ref(false),sheet=ref(false),error=ref(''),tab=ref('items');const pending=ref<FinanceCommand|null>(null);const operation=ref<FinanceCommand['kind']>('reconcile'),side=ref<'PAYER'|'PAYEE'>('PAYER'),payment=ref<SvSettlementPayment|null>(null),item=ref<SvSettlementItem|null>(null);const reason=ref(''),amount=ref(''),reference=ref(''),method=ref<'TRANSFER'|'CASH'|'OTHER'>('TRANSFER'),resolution=ref<'ACCEPT'|'REJECT'>('ACCEPT');
let generation=0;
const can=(permission:string,party?:'PAYER'|'PAYEE')=>(party==='PAYER'?access.value.payerActions:party==='PAYEE'?access.value.payeeActions:[...access.value.payerActions,...access.value.payeeActions]).includes('sv.settlement.'+permission);const storage=computed(()=>financeStorageKey(actor.value,m.value,no.value));const locked=computed(()=>busy.value||!!pending.value);const tabs=computed(()=>[{key:'items',label:t('svFinance.items')},{key:'payments',label:t('svFinance.payments')},...(can('audit')?[{key:'events',label:t('svFinance.events')}]:[])]);
async function read(section:'items'|'payments'|'events',append=false,run=generation){if(section==='events'&&!can('audit'))return;const cursor=section==='items'?itemNext.value:section==='payments'?paymentNext.value:eventNext.value;const q={managementNo:m.value,...(append&&cursor?{cursor}:{})};if(section==='items'){const p=await api.mSvSettlementItems(no.value,q);if(run!==generation)return;items.value=append?[...items.value,...p.records]:p.records;itemNext.value=p.nextCursor}else if(section==='payments'){const p=await api.mSvSettlementPayments(no.value,q);if(run!==generation)return;payments.value=append?[...payments.value,...p.records]:p.records;paymentNext.value=p.nextCursor}else{const p=await api.mSvSettlementEvents(no.value,q);if(run!==generation)return;events.value=append?[...events.value,...p.records]:p.records;eventNext.value=p.nextCursor}}
async function load(){const run=++generation;loading.value=true;failed.value=false;events.value=[];eventNext.value=null;access.value={payerActions:[],payeeActions:[]};try{const identity=(await api.mManagementContext()).actorKey;if(run!==generation)return;if(actor.value&&identity!==actor.value){pending.value=null;sheet.value=false}actor.value=identity;const result=await Promise.all([api.mSvSettlementBill(no.value,m.value),api.mSvSettlementActions(no.value,m.value),api.mSvFinanceCapability()]);if(run!==generation)return;[bill.value,access.value,capability.value]=result;if(tab.value==='events'&&!can('audit'))tab.value='items';await Promise.all([read('items',false,run),read('payments',false,run),...(can('audit')?[read('events',false,run)]:[])]);if(run!==generation)return;if(!pending.value){pending.value=restoreFinanceCommand(uni.getStorageSync(storage.value),actor.value,m.value,no.value);if(pending.value){operation.value=pending.value.kind;if(pending.value.kind==='register'){amount.value=String(pending.value.body.amountMinor/10**CURRENCIES[bill.value!.currency].minorUnits);method.value=pending.value.body.method}if('reason' in pending.value.body)reason.value=pending.value.body.reason||'';sheet.value=true}}}catch(e){if(run===generation){failed.value=true;error.value=(e as Error).message}}finally{if(run===generation){loading.value=false;if(!failed.value)loaded.value=true}}}
function open(kind:FinanceCommand['kind'],party:'PAYER'|'PAYEE'='PAYER',p:SvSettlementPayment|null=null,i:SvSettlementItem|null=null){if(locked.value)return;operation.value=kind;side.value=party;payment.value=p;item.value=i;reason.value='';amount.value='';reference.value='';method.value='TRANSFER';resolution.value='ACCEPT';error.value='';sheet.value=true}
function command():FinanceCommand{if(!bill.value)throw Error(t('svFinance.unavailable'));const common={resourceNo:payment.value?.paymentNo||no.value,billNo:no.value,key:idempotencyKey(),actorKey:actor.value};const base={managementNo:m.value,expectedRevision:bill.value.revision};switch(operation.value){case 'reconcile':return {...common,kind:'reconcile',body:{...base,side:side.value}};case 'dispute':if(!reason.value.trim())throw Error(t('svFinance.reasonRequired'));return {...common,kind:'dispute',body:{...base,side:side.value,reason:reason.value.trim()}};case 'resolve':if(!bill.value.disputeNo||!reason.value.trim())throw Error(t('svFinance.reasonRequired'));return {...common,kind:'resolve',body:{...base,disputeNo:bill.value.disputeNo,decision:resolution.value,reason:reason.value.trim()}};case 'adjust':{if(!item.value||!reason.value.trim())throw Error(t('svFinance.reasonRequired'));const signed=amount.value.startsWith('-')?-1:1;const value=signed*fixedMinor(amount.value.replace(/^-/u,''),CURRENCIES[bill.value.currency].minorUnits);if(!value)throw Error(t('svFinance.invalidAmount'));return {...common,kind:'adjust',body:{...base,clearingNo:item.value.clearingNo,payableDeltaMinor:value,reason:reason.value.trim()}}}case 'register':{const value=fixedMinor(amount.value,CURRENCIES[bill.value.currency].minorUnits);if(value<=0||!reference.value.trim())throw Error(t('svFinance.invalidPayment'));return {...common,kind:'register',body:{...base,amountMinor:value,paidAt:new Date().toISOString(),method:method.value,receiptReference:reference.value.trim(),evidenceRefs:[]}}}case 'receipt':if(!payment.value)throw Error(t('svFinance.unavailable'));return {...common,kind:'receipt',body:{managementNo:m.value,expectedRevision:payment.value.revision,receivedAt:new Date().toISOString()}};case 'void':if(!payment.value||!reason.value.trim())throw Error(t('svFinance.reasonRequired'));return {...common,kind:'void',body:{managementNo:m.value,expectedRevision:payment.value.revision,reason:reason.value.trim()}}}}
function clear(){uni.removeStorageSync(storage.value);pending.value=null;sheet.value=false;reference.value=''}
async function execute(){if(busy.value)return;const run=generation;busy.value=true;error.value='';try{const identity=(await api.mManagementContext()).actorKey;if(run!==generation)return;if(identity!==actor.value){pending.value=null;sheet.value=false;bill.value=null;items.value=[];payments.value=[];events.value=[];error.value=t('svFinance.operatorChanged');return;}if(!pending.value){pending.value=command();uni.setStorageSync(storage.value,encodeFinanceCommand(pending.value))}busy.value=true;const p=pending.value;switch(p.kind){case 'register':{const result=await api.mSvSettlementPaymentResolution(no.value,m.value,p.key);if(!result.found){if(!p.body.receiptReference){if(!reference.value.trim())throw Error(t('svFinance.reenterReceipt'));p.body.receiptReference=reference.value.trim()}await api.mSvSettlementRegister(p.resourceNo,p.body,p.key)}break}case 'reconcile':await api.mSvSettlementReconcile(p.resourceNo,p.body,p.key);break;case 'dispute':await api.mSvSettlementDispute(p.resourceNo,p.body,p.key);break;case 'resolve':await api.mSvSettlementResolveDispute(p.resourceNo,p.body,p.key);break;case 'adjust':await api.mSvSettlementAdjust(p.resourceNo,p.body,p.key);break;case 'receipt':await api.mSvSettlementReceipt(p.resourceNo,p.body,p.key);break;case 'void':await api.mSvSettlementVoid(p.resourceNo,p.body,p.key);break}if(run!==generation)return;clear();busy.value=false;await load()}catch(e){if(run!==generation)return;error.value=(e as Error).message==='amount'?t('svFinance.invalidAmount'):(e as Error).message;if(definiteGovernanceRejection(e)){clear();busy.value=false;await load()}}finally{if(run===generation)busy.value=false}}
async function more(section:'items'|'payments'|'events'){try{await read(section,true)}catch(e){error.value=(e as Error).message}}
onLoad(q=>{m.value=q?.m||'';no.value=q?.bill||'';void load()});
onShow(()=>{if(m.value&&!loading.value)void load()});onHide(()=>{generation++;loaded.value=false;bill.value=null;items.value=[];payments.value=[];events.value=[];access.value={payerActions:[],payeeActions:[]};pending.value=null;sheet.value=false;loading.value=false;busy.value=false});
</script>
<template><sh-scaffold title-key="svFinance.billDetail" :pending="loading" :failed="failed" @retry="load"><template v-if="bill">
 <view class="sh-card"><view class="sh-row sh-row--between"><text class="txt-strong">{{bill.billNo}}</text><text class="sh-chip">{{t('svFinance.states.'+bill.status)}}</text></view><sh-kv :label="t('svFinance.payer')" between>{{bill.payerEntityNo}}</sh-kv><sh-kv :label="t('svFinance.payee')" between>{{bill.payeeEntityNo}}</sh-kv><sh-kv :label="t('svFinance.payableMinor')" between>{{money(bill.payableMinor,bill.currency)}}</sh-kv><sh-kv :label="t('svFinance.registered')" between>{{money(bill.registeredPaymentMinor,bill.currency)}}</sh-kv><sh-kv :label="t('svFinance.confirmed')" between>{{money(bill.confirmedReceiptMinor,bill.currency)}}</sh-kv><text v-if="bill.billKind==='INTERNAL_RECON'" class="txt-sub sh-muted">{{t('svFinance.internal')}}</text></view>
 <view v-if="pending" class="sh-card"><text class="sh-hint">{{t('svGov.unknown')}}</text><view class="sh-btn" @tap="sheet=true">{{t('svGov.retry')}}</view></view><sh-tabs :items="tabs" :active="tab" @change="tab=$event"/>
 <template v-if="tab==='items'"><view v-for="row in items" :key="row.itemNo" class="sh-card"><sh-kv :label="t('svFinance.payableMinor')" between>{{money(row.amountMinor,bill.currency)}}</sh-kv><sh-kv :label="t('svFinance.rechargeStore')" between>{{row.rechargeStoreNo}}</sh-kv><sh-kv :label="t('svFinance.redemptionStore')" between>{{row.redemptionStoreNo}}</sh-kv><text class="txt-sub sh-muted">{{managementTime(row.occurredAt)}}<text v-if="row.carriedForward"> · {{t('svFinance.carriedForward')}}</text></text><view v-if="can('adjust')&&row.entryType==='USE'&&bill.billKind==='CROSS_ENTITY'&&!pending" class="sh-btn sh-btn--soft" @tap="open('adjust','PAYER',null,row)">{{t('svFinance.adjust')}}</view></view><view v-if="itemNext" class="sh-btn sh-btn--soft" @tap="more('items')">{{t('svGov.more')}}</view></template>
 <template v-if="tab==='payments'"><view v-for="row in payments" :key="row.paymentNo" class="sh-card"><view class="sh-row sh-row--between"><text class="txt-title">{{money(row.amountMinor,bill.currency)}}</text><text class="sh-chip">{{t('svFinance.states.'+row.status)}}</text></view><text class="txt-sub sh-muted">{{managementTime(row.paidAt)}}</text><view v-if="row.status==='REGISTERED'&&!pending" class="sh-cell sh-stack"><view v-if="can('receipt.confirm','PAYEE')" class="sh-btn" @tap="open('receipt','PAYEE',row)">{{t('svFinance.receipt')}}</view><view v-if="can('payment.void','PAYER')" class="sh-btn sh-btn--soft" @tap="open('void','PAYER',row)">{{t('svFinance.void')}}</view></view></view><sh-empty v-if="loaded && !payments.length" :text="t('svFinance.noPayments')"/><view v-if="paymentNext" class="sh-btn sh-btn--soft" @tap="more('payments')">{{t('svGov.more')}}</view></template>
 <template v-if="tab==='events'&&can('audit')"><view v-for="row in events" :key="row.eventNo" class="sh-card"><text class="txt-strong">{{t('svFinance.eventTypes.'+row.type)}}</text><view v-if="row.reason" class="sh-cell">{{row.reason}}</view><text class="txt-sub sh-muted">{{managementTime(row.occurredAt)}}</text></view><view v-if="eventNext" class="sh-btn sh-btn--soft" @tap="more('events')">{{t('svGov.more')}}</view></template>
 <view v-if="!pending" class="sh-card sh-stack"><template v-if="bill.status==='DRAFT'"><view v-if="can('reconcile','PAYER')&&!bill.payerReconciledBy" class="sh-btn" @tap="open('reconcile','PAYER')">{{t('svFinance.reconcilePayer')}}</view><view v-if="can('reconcile','PAYEE')&&!bill.payeeReconciledBy&&bill.billKind!=='INTERNAL_RECON'" class="sh-btn sh-btn--soft" @tap="open('reconcile','PAYEE')">{{t('svFinance.reconcilePayee')}}</view></template><view v-if="bill.status!=='DISPUTED'&&can('dispute')" class="sh-btn sh-btn--soft" @tap="open('dispute')">{{t('svFinance.dispute')}}</view><view v-if="bill.status==='DISPUTED'&&can('dispute.resolve')" class="sh-btn" @tap="open('resolve')">{{t('svFinance.resolve')}}</view><view v-if="capability?.settlementReady&&['RECONCILED','PART_PAID','WAIT_RECEIPT'].includes(bill.status)&&bill.billKind==='CROSS_ENTITY'&&bill.registeredPaymentMinor<bill.payableMinor&&can('payment.register','PAYER')" class="sh-btn" data-testid="register-payment" @tap="open('register')">{{t('svFinance.register')}}</view></view></template><text v-if="error" class="sh-hint">{{error}}</text>
 <sh-sheet :visible="sheet" :title="t('svFinance.operation.'+operation)" @close="!busy&&(sheet=false)"><view class="sh-card"><template v-if="operation==='register'"><view class="field"><text class="field__label">{{t('svFinance.amount')}}</text><input data-testid="payment-amount" v-model="amount" maxlength="17" type="digit" class="field__input" :disabled="locked"/></view><view v-if="!pending" class="sh-row"><view v-for="k in (['TRANSFER','CASH','OTHER'] as const)" :key="k" class="sh-chip" :class="{'sh-chip--primary':method===k}" @tap="method=k">{{t('svFinance.methods.'+k)}}</view></view><view class="field"><text class="field__label">{{t('svFinance.receiptReference')}}</text><input data-testid="receipt-reference" v-model="reference" class="field__input" maxlength="160" :disabled="busy"/></view></template>
 <view v-if="operation==='adjust'" class="field"><text class="field__label">{{t('svFinance.adjustmentAmount')}}</text><input v-model="amount" maxlength="18" class="field__input" :disabled="locked"/></view><view v-if="['dispute','resolve','adjust','void'].includes(operation)" class="field"><text class="field__label">{{t('svFinance.reason')}}</text><textarea v-model="reason" class="field__input" maxlength="255" :disabled="locked"/></view><view v-if="operation==='resolve'&&!pending" class="sh-row"><view v-for="decision in (['ACCEPT','REJECT'] as const)" :key="decision" class="sh-chip" :class="{'sh-chip--primary':resolution===decision}" @tap="resolution=decision">{{t('svFinance.decisions.'+decision)}}</view></view><text v-if="operation==='receipt'" class="sh-hint">{{t('svFinance.receiptHint')}}</text></view><text v-if="pending" class="sh-hint">{{t('svGov.unknown')}}</text><text v-if="error" class="sh-hint">{{error}}</text><view data-testid="finance-submit" class="sh-btn" :class="{'is-disabled':busy}" @tap="execute">{{t(pending?'svGov.retry':'svFinance.submit')}}</view></sh-sheet>
</sh-scaffold></template>
